import { createHash, randomBytes } from 'node:crypto';
import { mkdir, open } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';

/**
 * M2 document storage (design section 5.4).
 *
 * Documents live in a private storage folder outside the repository. The
 * storage path is generated by the server: a digest-derived bucket plus a
 * random file token. The client filename is display metadata and is never part
 * of the path, so a hostile filename can never influence where bytes land.
 */

export const DEFAULT_DOCUMENT_MAX_BYTES = 5 * 1024 * 1024;

export const ALLOWED_DOCUMENT_MIME_TYPES = [
  'application/pdf',
  'image/png',
  'image/jpeg',
  'text/plain',
  'text/csv'
] as const;

export type AllowedDocumentMimeType = (typeof ALLOWED_DOCUMENT_MIME_TYPES)[number];

const MAGIC_SIGNATURES: readonly { mime: AllowedDocumentMimeType; bytes: readonly number[] }[] = [
  { mime: 'application/pdf', bytes: [0x25, 0x50, 0x44, 0x46] },
  { mime: 'image/png', bytes: [0x89, 0x50, 0x4e, 0x47] },
  { mime: 'image/jpeg', bytes: [0xff, 0xd8, 0xff] }
];

export function documentStorageRoot(env: NodeJS.ProcessEnv = process.env): string {
  const configured = env.DOCUMENT_STORAGE_DIR;
  if (typeof configured === 'string' && configured.length > 0) return configured;
  return path.join(os.tmpdir(), 'kanei-crm-mvp-document-storage');
}

export function documentMaxBytes(env: NodeJS.ProcessEnv = process.env): number {
  const configured = env.DOCUMENT_MAX_BYTES;
  if (typeof configured === 'string' && configured.length > 0) {
    const parsed = Number(configured);
    if (Number.isFinite(parsed) && parsed > 0) return Math.floor(parsed);
  }
  return DEFAULT_DOCUMENT_MAX_BYTES;
}

export function computeSha256(bytes: Buffer): string {
  return createHash('sha256').update(bytes).digest('hex');
}

/**
 * Content sniffing over the first bytes. Only used to reject uploads whose
 * declared type contradicts the actual content; text-like formats have no
 * signature and are accepted on the declared type alone.
 */
export function detectMimeType(bytes: Buffer): string | null {
  for (const signature of MAGIC_SIGNATURES) {
    if (signature.bytes.every((byte, index) => bytes[index] === byte)) {
      return signature.mime;
    }
  }
  return null;
}

export type DocumentContentCheck =
  | {
      ok: true;
      sha256: string;
      byteSize: number;
      declaredMimeType: string;
      detectedMimeType: string | null;
      sizeCheckPassed: true;
      typeCheckPassed: true;
    }
  | { ok: false; code: 'DOCUMENT_EMPTY' | 'DOCUMENT_TOO_LARGE' | 'DOCUMENT_TYPE_REJECTED' | 'DOCUMENT_CONTENT_MISMATCH'; message: string };

/**
 * Server-side size and type checks. They run before any persistence and before
 * any file write, so a rejected upload leaves nothing behind (T-04 shape).
 */
export function evaluateDocumentContent(
  bytes: Buffer,
  declaredMimeType: unknown,
  env: NodeJS.ProcessEnv = process.env
): DocumentContentCheck {
  if (bytes.length === 0) {
    return { ok: false, code: 'DOCUMENT_EMPTY', message: 'document content is empty' };
  }
  const maxBytes = documentMaxBytes(env);
  if (bytes.length > maxBytes) {
    return {
      ok: false,
      code: 'DOCUMENT_TOO_LARGE',
      message: `document exceeds the ${maxBytes} byte limit`
    };
  }
  if (typeof declaredMimeType !== 'string' || !(ALLOWED_DOCUMENT_MIME_TYPES as readonly string[]).includes(declaredMimeType)) {
    return {
      ok: false,
      code: 'DOCUMENT_TYPE_REJECTED',
      message: `contentType must be one of ${ALLOWED_DOCUMENT_MIME_TYPES.join(', ')}; received ${String(declaredMimeType)}`
    };
  }
  const detected = detectMimeType(bytes);
  if (detected !== null && detected !== declaredMimeType) {
    return {
      ok: false,
      code: 'DOCUMENT_CONTENT_MISMATCH',
      message: `content looks like ${detected} but contentType declares ${declaredMimeType}`
    };
  }
  return {
    ok: true,
    sha256: computeSha256(bytes),
    byteSize: bytes.length,
    declaredMimeType,
    detectedMimeType: detected,
    sizeCheckPassed: true,
    typeCheckPassed: true
  };
}

/**
 * Randomized storage path for a digest. The bucket comes from the digest and
 * the file token from server randomness; no part of the client filename is
 * ever used.
 */
export function storagePathForDigest(root: string, sha256: string, token: string): string {
  return path.join(root, 'documents', sha256.slice(0, 2), sha256.slice(2, 4), `${token}.bin`);
}

export interface StoredFile {
  storagePath: string;
  bytesWritten: number;
}

/**
 * Writes the bytes once under a fresh random path (mode 0600, folders 0700).
 * Callers first check document_versions for an existing row carrying the same
 * digest and reuse its path, so identical bytes uploaded to another project
 * keep referencing one physical file (T-26).
 */
export async function writeStoredFile(root: string, sha256: string, bytes: Buffer): Promise<StoredFile> {
  const token = randomBytes(16).toString('hex');
  const target = storagePathForDigest(root, sha256, token);
  await mkdir(path.dirname(target), { recursive: true, mode: 0o700 });
  const handle = await open(target, 'wx', 0o600);
  try {
    await handle.writeFile(bytes);
  } finally {
    await handle.close();
  }
  return { storagePath: target, bytesWritten: bytes.length };
}
